"""Copy actual saved aggregate outputs and create a readable local index."""
import html,json,shutil,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT))
from tests.test_imported_reports import reports
HERE=Path(__file__).resolve().parent;DATA=ROOT/'data/iteration-38-empirical-20261027';OUT=DATA/'reports';OUT.mkdir(parents=True,exist_ok=True)
items=[]
for store in ['35','36','37','38']:
 for value in reports(store):
  source=DATA/('native-'+store)/('report-'+value['id']+'.json');target=OUT/(value['id']+'.json');shutil.copyfile(source,target)
  r=value['report'];s=value['source_summary'];native=r['native_population'];coverage_only=r['population']['label_origin']=='native_coverage_only'
  items.append(dict(id=value['id'],source=s['source_name'],version=s['source_version'],view=s['view_label'],unit=s['unit'],examples=r['observed_windows'],original_error_events=None if coverage_only else native['eligible_events'],fully_annotated_examples=None if coverage_only else native['annotated_windows'],mapped_events=r['eligible_events'],unmapped_events=r['unmapped_events'],categories_with_examples=sum(l['events']>0 for l in r['leaves']),mapping=s['mapping_version'],native_relationship_rows=len(r['native_pairs']),source_release=r['population']['release'],source_manifest=s['source_manifest'],file=target.name,coverage=s['coverage']))
items.sort(key=lambda v:(v['source'],v['version'],v['view']))
(DATA/'report-index.json').write_text(json.dumps(items,indent=2)+'\n')
lines=['# Imported-source empirical reports','','52 source views are saved through the production report owner. Each view is a separate descriptive report; overlapping task views, related releases and repeated imports are not independent learner populations. Exact values and complete source/mapping metadata are in the linked aggregate JSON downloads. No original sentences, correction texts, recordings or participant records are copied into these report exports.','','Original error totals count eligible source annotations. Complete-window prevalence and word exposure exclude windows with unresolved or invalid labels; each measurement retains its own numerator and denominator. Project mappings are derived rules, not full annotation of all122categories. Missing category, opportunity, difficulty or relationship evidence stays **Not measured**. Native annotation counts do not independently verify a recording or estimate rates for all English learners.','','| Source and view | Examples in this view | Unit | Original annotated errors | Fully annotated examples | Categories with mapped examples | Values |','|---|---:|---|---:|---:|---:|---|']
for v in items:
 show=lambda n:'Not measured' if n is None else f'{n:,}'
 lines.append('| '+v['source']+' — '+v['view']+' | '+f"{v['examples']:,}"+' | '+v['unit']+' | '+show(v['original_error_events'])+' | '+show(v['fully_annotated_examples'])+' | '+(str(v['categories_with_examples'])+' of 122' if v['original_error_events'] is not None else 'Not annotated')+' | [Download](../../data/iteration-38-empirical-20261027/reports/'+v['file']+') |')
lines+=['','## How to read the sources','','- FCE/W&I use one original M2 member and one selected annotator per sentence. Native labels retain all eligible edits; only narrow supported rules add a Tangerine category. The withheld W&I test view has no supplied error labels.','- L2-ARCTIC keeps read prompts and Suitcase stories separate. Manual phone operations and their actual utterance denominators are retained. Phone intervals, silence and automatic alignments are not word-token or correct-use exposure.','- JFLEG preserves original sentences and four alternative corrections. Alternatives are not simultaneous errors.','- SpeechOcean covers 5,000 rated utterances and 5,245 original recordings; ratings do not establish localized binary error labels.','- EdAcc, ELRD, DiPlomat and DRAL preserve their original segment/turn/task/fragment views. Accents, ASR, task answers and translations are not error gold; short/long DRAL fragments and related versions are not independent populations.','','See [research and interpretation](RESEARCH.md), [the complete contract](../../specification/v2/docs/empirical-source-reports.md) and [the iteration report](REPORT.md). Reports live in retained test-owned application stores and local exports; the user’s running workspace was not modified.']
assert len(items)==52,len(items)
(HERE/'REPORTS.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'source_views':len(items),'source_families':len(set(v['source'] for v in items)),'exports':str(OUT)},indent=2))
